package org.sleepwell.app;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;
/** Temporal event acceptance, separate from clip amplitude and the opt-in cue's score/strength policy. */
public final class SoundSensitivityActivity extends androidx.activity.ComponentActivity implements SoundSensitivitySave.Observer {
 private SoundSensitivity draft;private String readError="";private SoundSensitivitySave job;private SoundSensitivitySave.State operation;private Dialog picker;private boolean categories;private String selectionError="";
 @Override public void onCreate(Bundle saved){super.onCreate(saved);getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});RecordUi.review(this);Object old=getLastCustomNonConfigurationInstance();job=old instanceof SoundSensitivitySave?(SoundSensitivitySave)old:new SoundSensitivitySave(SoundSensitivitySettings.editor(getApplicationContext()));SoundSensitivitySettings.Read initial;try{initial=job.port.read();}catch(RuntimeException failure){initial=new SoundSensitivitySettings.Read(SoundSensitivity.DEFAULT,"Saved settings could not be read. Review and save to enable analysis.");}draft=initial.policy;readError=initial.error;if(saved!=null){categories=saved.getBoolean("categories");selectionError=saved.getString("selectionError","");readError=saved.getString("readError",readError);try{draft=SoundSensitivityJson.decode(saved.getString("draft"));}catch(IllegalArgumentException invalid){draft=SoundSensitivity.DEFAULT;readError="Draft settings are invalid. Defaults are being used.";}}job.observe(this);}
 @Override public Object onRetainCustomNonConfigurationInstance(){return job;}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("draft",SoundSensitivityJson.encode(draft));out.putString("readError",readError);out.putBoolean("categories",categories);out.putString("selectionError",selectionError);}
 @Override public void changed(SoundSensitivitySave.State state){if(isDestroyed())return;operation=state;if(state.busy&&state.policy!=null)draft=state.policy;if(state.saved)readError="";render();}
 private void render(){boolean busy=operation!=null&&operation.busy;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);LinearLayout header=RecordUi.header(body,categories?"Detected categories":"Sound sensitivity",()->{if(categories){categories=false;selectionError="";render();}else finish();});header.setMinimumHeight(Design.dp(this,52));header.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));Design.space(body,14);Design.text(body,categories?"Keep selected estimates next night. Existing records stay unchanged.":"Minimum duration of accepted estimates. Applies next night.",14,400,Design.MUTED);Design.space(body,16);
  if(categories){for(String key:SoundSensitivity.SELECTABLE){android.widget.Switch toggle=Design.toggle(body,SoundSensitivity.label(key),null,draft.includes(key),on->{try{draft=draft.include(key,on);selectionError="";}catch(IllegalArgumentException last){selectionError="Keep at least one category on.";}render();});toggle.setContentDescription("Include "+SoundSensitivity.label(key));toggle.setMinimumWidth(Design.dp(this,48));toggle.setMinimumHeight(Design.dp(this,48));RecordUi.enabled(toggle,!busy);Design.space(body,6);}Design.space(body,8);Design.text(body,"Other sounds is independent. Off labels are dropped, not relabeled.",13,400,Design.MUTED);Design.space(body,8);Design.text(body,"Custom selection saves estimates only. Sound clips require all categories.",13,500,Design.BROWN);}
  else{View selected=Design.item(body,"wave","Detected categories",draft.selectedCount()+" of 6",()->{categories=true;render();});selected.setContentDescription("Choose detected categories");RecordUi.enabled(selected,!busy);Design.line(body);if(!draft.allIncluded()){Design.space(body,8);Design.text(body,"Selected estimates only · sound clips off next night.",12,500,Design.BROWN);Design.space(body,4);}
  for(String key:SoundSensitivity.CATEGORIES){View row=Design.item(body,"wave",SoundSensitivity.label(key),SoundSensitivity.choice(draft.windows(key)),()->choose(key));row.setContentDescription("Minimum duration "+SoundSensitivity.label(key));RecordUi.enabled(row,!busy);Design.line(body);}
  Design.space(body,16);Design.text(body,"High keeps shorter events and can increase false detections. Model scores stay unchanged.",13,400,Design.MUTED);Design.space(body,8);View reset=Design.item(body,"undo","Restore defaults",null,()->{draft=SoundSensitivity.DEFAULT;selectionError="";render();});reset.setContentDescription("Restore sound sensitivity defaults");RecordUi.enabled(reset,!busy);}
  LinearLayout footer=RecordUi.footer(body);String message=!selectionError.isEmpty()?selectionError:operation!=null&&!operation.error.isEmpty()?operation.error:readError;boolean saved=operation!=null&&operation.saved&&draft.equals(operation.policy);if(saved&&selectionError.isEmpty())message="Saved for the next night.";TextView status=Design.text(footer,message,13,500,message.isEmpty()?Design.MUTED:!readError.isEmpty()||operation!=null&&!operation.error.isEmpty()?0xffa93919:Design.BROWN);status.setContentDescription("Sound sensitivity status");status.setVisibility(message.isEmpty()?View.GONE:View.VISIBLE);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);View save=Design.button(footer,busy?"Saving…":"Save sensitivity",true,()->{selectionError="";job.start(draft);});RecordUi.enabled(save,!busy);
 }
 private void choose(String key){if(operation!=null&&operation.busy||picker!=null&&picker.isShowing())return;String[] values={"1 accepted window · about 1 sec (High)","2 accepted windows · about 2 sec (Default)","3 accepted windows · about 3 sec (Low)"};picker=SleepPicker.choices(this,SoundSensitivity.label(key)+" duration",values,draft.windows(key)-1,n->{draft=draft.with(key,n+1);render();});}
 boolean awaitWorkers(long timeout)throws InterruptedException{return job.awaitClosed(timeout);}
 @Override protected void onDestroy(){if(picker!=null)picker.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 private void back(){if(categories){categories=false;selectionError="";render();}else finish();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
